<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {voiceApi as api,labels} from '../voice/operations'
import {isEmbedded,voiceBase,voiceAuth} from '../voice/embed-session'
import VoiceCallingPanel from './VoiceCallingPanel.vue'
import VoiceDispositionForm from './VoiceDispositionForm.vue'
const props=defineProps({catalog:Object,view:{type:String,default:'supervisor'}})
const state=ref(null),selected=ref(''),form=ref(null),error=ref(''),notice=ref(''),busy=ref(false),armed=ref(false),authorization=ref(false),method=ref('programmable_voice'),dialer=ref(null),countdown=ref(0)
const queue=computed(()=>state.value?.queues.find(q=>q.id===Number(selected.value)))
let timer=null,disposed=false,polling=false,claimKey=null,epoch=0,nextAt=0
function pause(){armed.value=false;epoch++;countdown.value=0}
async function refresh(){const s=await api('/operations/queues');if(props.view==='agent')s.queues=s.queues.filter(q=>q.agent_ids.includes(props.catalog.user_id));if(!disposed)state.value=s}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message;pause()}finally{busy.value=false}}
function edit(q=null){form.value=q?{...q,agent_ids:[...q.agent_ids]}:{name:'',campaign_id:'',mode:'preview',strategy:'fifo',wrapup_seconds:30,agent_ids:[props.catalog.user_id],revision:0}}
async function save(){const q=form.value;await api('/operations/queues'+(q.id?'/'+q.id:''),q.id?'PUT':'POST',{name:q.name,campaign_id:Number(q.campaign_id),mode:q.mode,strategy:'fifo',wrapup_seconds:q.wrapup_seconds,agent_ids:q.agent_ids,revision:q.revision});form.value=null;await refresh()}
async function presence(status){if(status!=='available')pause();await api('/queues/presence','POST',{status,pause_reason:status==='paused'?'Pausa na operação real':null});await refresh()}
async function online(){if(!authorization.value||!queue.value)return;const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});stream.getTracks().forEach(t=>t.stop());await presence('available');if(queue.value.mode==='progressive')await startProgressive()}
async function claim(auto=false){const version=epoch;claimKey ||= crypto.randomUUID();const result=await api('/operations/queues/'+queue.value.id+'/claim','POST',{idempotency_key:claimKey});claimKey=null;await refresh();if(!result.reservation){notice.value=[result.message,...Object.entries(result.reasons||{}).map(([k,v])=>`${v}: ${k}`)].join(' ');nextAt=Date.now()+Math.max(5,result.retry_after||15)*1000;return}if(auto&&armed.value&&version===epoch&&!disposed){await nextTick();await dialer.value?.startAuthorized()}}
async function startProgressive(){if(!authorization.value)return;pause();armed.value=true;nextAt=Date.now()+5000;notice.value='Progressivo iniciado. Você pode parar a sequência a qualquer momento.'}
async function tick(){if(disposed||polling||busy.value)return;polling=true;try{if(props.view==='agent')await api('/queues/heartbeat','POST',{});await refresh();if(!armed.value||disposed)return;if(state.value.presence?.status!=='available'){pause();return}if(queue.value?.status!=='running'){notice.value='Aguardando a supervisão habilitar a fila.';return}if(state.value.current){nextAt=Date.now()+5000;if(state.value.current.call?.status==='unknown'){error.value='Chamada sem confirmação final. Consulte a Twilio antes de continuar.';pause()}return}const wrap=state.value.presence?.available_after;const after=wrap?Date.parse(/[Zz]|[+-]\d\d:\d\d$/.test(wrap)?wrap:wrap.replace(' ','T')+'Z'):0;countdown.value=Math.max(0,Math.ceil((Math.max(nextAt,after)-Date.now())/1000));if(!countdown.value)await claim(true)}catch(e){if(!disposed){error.value=e.message;pause()}}finally{polling=false}}
onMounted(()=>{run(refresh);timer=setInterval(tick,5000)})
function beforeUnload(e){if(props.view==='agent'&&(armed.value||state.value?.current)){e.preventDefault();e.returnValue=''}}
function pageHide(){if(props.view!=='agent')return;if(isEmbedded()){fetch(voiceBase()+'/queues/presence',{method:'POST',credentials:'omit',keepalive:true,headers:{'Content-Type':'application/json',...voiceAuth()},body:JSON.stringify({status:'offline'})}).catch(()=>{});return}const token=document.querySelector('meta[name="csrf-token"]').content;navigator.sendBeacon('/api/voice/queues/presence',new Blob([JSON.stringify({status:'offline',_token:token})],{type:'application/json'}))}
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);window.addEventListener('pagehide',pageHide)})
onBeforeUnmount(()=>{disposed=true;pause();clearInterval(timer);window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('pagehide',pageHide);if(props.view==='agent')api('/queues/presence','POST',{status:'offline'}).catch(()=>{})})
async function requestLeave(fn){if(props.view==='agent'&&state.value?.current){error.value='Conclua a chamada e a tabulação antes de sair da operação.';return}if(props.view==='agent'){pause();await api('/queues/presence','POST',{status:'offline'})}fn()}
async function failure(){pause();await presence('paused')}
defineExpose({requestLeave})
</script>
<template><section class="live-operation">
 <h3>{{view==='agent'?'Disponibilidade e fila':'Supervisão das filas'}}</h3>
 <p>{{view==='agent'?'Escolha sua fila e fique disponível. A próxima chamada respeita o horário, o intervalo e as regras da campanha.':'Prepare as filas e acompanhe a disponibilidade da equipe. As chamadas progressivas dependem de um agente disponível na tela Minha operação.'}}</p>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
 <div class="op-tabs"><button v-if="view==='supervisor'&&catalog.can_manage" class="secondary" @click="edit()">Nova fila real</button><button class="secondary" :disabled="busy" @click="run(refresh)">Atualizar filas</button></div>
 <template v-if="view==='supervisor'"><form v-if="form" class="table-card op-box" @submit.prevent="run(save)"><h3>{{form.id?'Editar':'Criar'}} fila</h3><div class="op-grid"><label>Nome da fila<input v-model="form.name" required maxlength="160"></label><label>Campanha<select v-model="form.campaign_id" required :disabled="!!form.id"><option value="">Selecione</option><option v-for="c in catalog.campaigns" :value="c.id">{{c.name}}</option></select></label><label>Modo<select v-model="form.mode"><option value="preview">Preview</option><option value="progressive">Progressivo</option></select></label><label>Pós-atendimento (segundos)<input type="number" v-model.number="form.wrapup_seconds" min="0" max="120" required></label></div><fieldset><legend>Atendentes</legend><label v-for="u in catalog.agents" class="check"><input type="checkbox" v-model="form.agent_ids" :value="u.id">{{u.name}}</label></fieldset><p>Distribuição por menos tentativas, seguida da tentativa mais antiga. Pause a fila e conclua as reservas antes de editar.</p><button class="primary" :disabled="busy||!form.agent_ids.length">Salvar fila</button> <button type="button" class="secondary" @click="form=null">Fechar</button></form>

 <div class="table-card op-box"><h3>Disponibilidade da equipe</h3><table><thead><tr><th>Atendente</th><th>Estado</th></tr></thead><tbody><tr v-for="a in state?.team||[]" :key="a.id"><td>{{a.name}}</td><td>{{({available:'Disponível',paused:'Pausado',offline:'Offline'})[a.status]||'Offline'}}</td></tr></tbody></table></div></template>
 <label>Fila real<select aria-label="Fila real" v-model="selected" :disabled="armed||!!state?.current" @change="pause();claimKey=null"><option value="">Selecione</option><option v-for="q in state?.queues||[]" :value="q.id">{{q.name}} · {{labels[q.status]}}</option></select></label>
 <article v-if="queue" class="table-card op-box"><h3>{{queue.name}}</h3><p>{{queue.mode==='progressive'?'Progressivo':'Preview'}} · {{labels[queue.status]}} · {{queue.wrapup_seconds}} s de pós-atendimento</p>
 <div v-if="view==='supervisor'" class="op-tabs"><span v-for="(n,s) in queue.counts" :key="s">{{labels[s]||s}}: {{n}}</span><button class="secondary" :disabled="busy" @click="run(async()=>{await api('/operations/queues/'+queue.id+'/status','POST',{status:queue.status==='running'?'paused':'running'});await refresh()})">{{queue.status==='running'?'Pausar fila':'Habilitar fila'}}</button><button class="secondary" @click="edit(queue)">Editar fila</button></div>
 <template v-else><label>Método para a sequência<select aria-label="Método para a sequência" v-model="method" :disabled="armed||!!state?.current"><option value="programmable_voice">Twilio API</option><option v-if="!isEmbedded()" value="sip_trunk">SIP / Asterisk</option></select></label>
 <label class="check"><input type="checkbox" v-model="authorization" :disabled="armed">Estou pronto para atender chamadas reais desta fila.</label>
 <div class="op-tabs"><button class="primary" :disabled="busy||!authorization||armed||!!state?.current" @click="run(online)">Ficar disponível</button><button class="secondary" :disabled="busy" @click="run(()=>presence('paused'))">Pausar atendimento</button><button class="secondary" :disabled="busy" @click="run(()=>presence('offline'))">Ficar offline</button></div>
 <p role="status">{{state?.presence?.status==='available'?'Disponível':state?.presence?.status==='paused'?'Pausado':'Offline'}}{{armed?' · Progressivo ativo':''}}</p>
 <p v-if="armed">{{state?.current?'Conclua a chamada e a tabulação.':queue.status!=='running'?'Aguardando a supervisão habilitar a fila.':'Aguardando o próximo contato elegível. Consulta em até '+Math.max(countdown,5)+' segundos.'}}</p>
 <button v-if="queue.mode==='preview'" class="primary" :disabled="busy||!!state?.current||queue.status!=='running'||state?.presence?.status!=='available'" @click="run(()=>claim())">Reservar próximo contato</button></template></article>
 <article v-if="view==='agent'&&state?.current" class="table-card op-box"><h3>Contato reservado: {{state.current.contact.name}}</h3><p>{{state.current.contact.phone}} · {{labels[state.current.status]}} · {{state.current.queue.name}}</p>
 <button v-if="!state.current.call_id" class="secondary" :disabled="busy" @click="run(async()=>{pause();await api('/operations/reservations/'+state.current.id+'/cancel','POST',{});await refresh()})">Devolver contato à fila</button>
 <VoiceCallingPanel v-if="state.current.status!=='tabulation'" :key="state.current.id" ref="dialer" :reservation="state.current" :initial-method="method" compact @failed="run(failure)"/>
 <VoiceDispositionForm v-else :key="state.current.call.id" :call="{...state.current.call,destination:state.current.contact.phone}" :codes="catalog.codes" @saved="run(refresh)" @cancel="pause"/></article>
 <p v-if="view==='agent'">Mantenha esta aba aberta. Pausar impede novas tentativas e permite concluir a ligação atual. Uma chamada sem resultado confirmado bloqueia a continuação até conferência.</p>
 </section></template>
<style scoped>
.live-operation{min-width:0}.live-operation p{color:#727b65;line-height:1.65}.live-operation .op-box{padding:24px;margin:20px 0}.live-operation .op-box>h3{padding:0;margin:0 0 16px}.live-operation .op-tabs{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:18px 0}.live-operation label:not(.check){display:flex;flex-direction:column;gap:8px;margin:16px 0;font-size:13px;font-weight:600}.live-operation select{width:100%;max-width:100%;min-width:0;padding:12px;border:1px solid #dddccd;border-radius:10px;background:white}.live-operation .check{display:flex;gap:10px;align-items:center;font-size:13px;line-height:1.6;margin:18px 0}.live-operation .check input{width:auto;flex-shrink:0}.live-operation fieldset{border:0;padding:0}.live-operation .op-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:16px}.live-operation button:disabled{opacity:.55}.live-operation .error{color:#9e302d}@media(max-width:650px){.live-operation .op-box{padding:16px}.live-operation .op-tabs{gap:8px}}
</style>
